<?php
/** 成员 A | 视图：团队主页、个人中心、审核与资料发布。 */
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function form($action,$extra=[]){echo '<form method="post">';foreach(['action'=>$action,'csrf'=>$_SESSION['csrf']]+$extra as $k=>$v)echo '<input type="hidden" name="'.h($k).'" value="'.h($v).'">';}
function endform($label){echo '<button>'.h($label).'</button></form>';}
$t=$m->row('SELECT * FROM team_profiles WHERE id=1');$members=$m->rows('SELECT * FROM team_members ORDER BY display_order');$pages=['team'=>'团队主页','catalog'=>'比赛与球队','downloads'=>'作业下载'];if($uid)$pages['profile']='个人中心';else $pages['auth']='注册 / 登录';if($admin)$pages['admin']='管理后台';
?><!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($pages[$page]??'世界杯')?></title><link rel="stylesheet" href="style.css"><header><strong>看球日历 · 世界杯</strong><nav><?php foreach($pages as $k=>$v):?><a href="?p=<?=$k?>"><?=h($v)?></a> <?php endforeach;?></nav><?php if($uid){form('logout');endform('退出 · '.$me['username']);}?></header><main><small>WORLD CUP / <?=h($pages[$page]??'')?></small>
<?php if($notice):?><p role="status"><?=h($notice)?></p><?php endif;?>
<?php if($page==='team'):?><h1><?=h($t['name'])?></h1><p><?=nl2br(h($t['intro']))?></p><?php if($t['contact']):?><p>联系：<?=h($t['contact'])?></p><?php endif;?>
<h2>成员分工</h2><div class="grid"><?php foreach($members as $r):?><article><b>成员 <?=h($r['label'])?></b><p><?=nl2br(h($r['intro']))?></p></article><?php endforeach;?></div>
<h2>留言板</h2><?php if($uid){form('message');?><label>写留言<textarea name="body" required></textarea></label><?php endform('提交审核');}else echo '<a href="?p=auth">登录后留言</a>';
$rows=$m->rows("SELECT u.username,m.body,m.created_at FROM messages m JOIN users u ON u.id=m.user_id WHERE status='approved' ORDER BY m.id DESC LIMIT 50");if(!$rows)echo '<p>暂无公开留言。</p>';foreach($rows as $r):?><article><b><?=h($r['username'])?></b> · <?=h($r['created_at'])?><p><?=nl2br(h($r['body']))?></p></article><?php endforeach;?>
<?php elseif($page==='auth'):?><h1>球迷账号</h1><div class="grid"><?php foreach(['login'=>'登录','register'=>'注册'] as $a=>$label):?><article><h2><?=$label?></h2><?php form($a);?><label>用户名<input name="username" required autocomplete="username"></label><label>密码<input type="password" name="password" required autocomplete="<?=$a==='login'?'current-password':'new-password'?>"></label><?php if($a==='register')echo '<p>用户名：3–32 位字母、数字或下划线。密码：10–72 字节。</p>';endform($label);?></article><?php endforeach;?></div>
<?php elseif($page==='catalog'||$page==='profile'):?><h1><?=$page==='profile'?'我的收藏':'比赛与球队'?></h1><?php foreach(['match'=>'比赛','team'=>'球队'] as $type=>$label):?><h2><?=$label?></h2><div class="grid"><?php $rows=$m->catalog($type,$uid,$page==='profile');if(!$rows)echo '<p>暂无条目。</p>';foreach($rows as $r):?><article><b><?=h($r['title'])?></b><?php if($uid){form('favorite',['type'=>$type,'id'=>$r['id'],'save'=>$r['saved']?'0':'1','from'=>$page]);endform($r['saved']?'取消收藏':'收藏');}else echo '<p><a href="?p=auth">登录后收藏</a></p>';?></article><?php endforeach;?></div><?php endforeach;?>
<?php elseif($page==='downloads'):?><h1>作业下载</h1><?php $rows=$m->rows('SELECT a.*,m.label FROM assignments a LEFT JOIN team_members m ON m.id=a.member_id ORDER BY a.id');foreach(['团队','个人'] as $cat):?><h2><?=$cat?>材料</h2><?php $count=0;foreach($rows as $r){if(($r['member_id']?'个人':'团队')!==$cat)continue;$count++;echo '<p><a href="?p=file&amp;id='.(int)$r['id'].'">'.h($r['title']).'</a> '.h($r['label']).'</p>';}if(!$count)echo '<p>暂无已发布材料。</p>';endforeach;?>
<?php elseif($page==='admin'):?><h1>管理后台</h1><h2>团队资料</h2><?php form('updateTeam');?><label>队名<input name="name" required value="<?=h($t['name'])?>"></label><label>介绍<textarea name="intro" required><?=h($t['intro'])?></textarea></label><label>联系方式<input name="contact" value="<?=h($t['contact'])?>"></label><?php endform('保存团队资料');foreach($members as $r){form('updateMember',['id'=>$r['id']]);?><label>成员 <?=h($r['label'])?><textarea name="intro" required><?=h($r['intro'])?></textarea></label><?php endform('保存成员介绍');}?>
<h2>留言审核</h2><?php $rows=$m->rows('SELECT m.*,u.username FROM messages m JOIN users u ON u.id=m.user_id ORDER BY m.id DESC');if(!$rows)echo '<p>暂无留言。</p>';foreach($rows as $r):?><article><b><?=h($r['username'])?> · <?=$r['status']==='approved'?'已发布':'待审核'?></b><p><?=h($r['body'])?></p><?php if($r['status']!=='approved'){form('approve',['id'=>$r['id']]);endform('审核通过');}form('delete',['id'=>$r['id']]);endform('删除留言');?></article><?php endforeach;?>
<h2>发布下载资料</h2><?php form('publish');?><label>资料标题<input name="title" required></label><label>白名单文件<select name="file_key"><?php foreach($files as $k=>$v):?><option value="<?=h($k)?>"><?=h($v)?></option><?php endforeach;?></select></label><label>归属<select name="member_id"><option value="">团队</option><?php foreach($members as $r):?><option value="<?=(int)$r['id']?>"><?=h($r['label'])?></option><?php endforeach;?></select></label><?php endform('发布或更新');foreach($m->rows('SELECT * FROM assignments ORDER BY id') as $r){form('unpublish',['id'=>$r['id']]);endform('撤下：'.$r['title']);}endif;?></main></html>
